## The three scope types

```js
var globalVar = 'I am global';

function outer() {
  var funcVar = 'function scoped'; // only accessible inside outer()

  if (true) {
    let blockVar   = 'block scoped';  // only accessible in this {}
    const alsoBlock = 'also block';   // same
    var notBlock   = 'still function'; // hoisted to function scope!
  }

  console.log(funcVar);    // ✅
  console.log(notBlock);   // ✅  (var leaks out of the block)
  // console.log(blockVar); // ❌ ReferenceError
}
```

## Scope chain lookup

```js
const x = 'global';

function outer() {
  const x = 'outer';
  function inner() {
    // x not declared here — walks up the chain:
    console.log(x); // 'outer' (found in outer's scope)
  }
  inner();
}
```

## Closures capture scope

```js
function makeCounter() {
  let count = 0;            // captured in closure
  return () => ++count;     // inner fn holds reference to count
}

const inc = makeCounter();
inc(); // 1
inc(); // 2  — count persists between calls
```

## Module scope

ES modules each have their own module scope — `import`/`export` cross module boundaries explicitly. Nothing bleeds into global scope.

