## undefined — declared, no value

```js
let x;
console.log(x);          // undefined — no error
console.log(typeof x);   // 'undefined'
console.log(x === undefined); // true
```

## Not defined — no declaration at all

```js
console.log(y);        // ReferenceError: y is not defined
console.log(typeof y); // 'undefined' — typeof is safe!
```

## Practical safe check

```js
// When you don't know if the variable was declared:
if (typeof myLib !== 'undefined') {
  myLib.init();
}

// Or use optional chaining on globalThis:
globalThis.myLib?.init();
```

## Function parameters

```js
function greet(name) {
  // name is declared (parameter), but undefined if not passed
  console.log(name);         // undefined
  console.log(name === undefined); // true
}
greet(); // called without argument
```

## Object properties

```js
const obj = { a: 1 };
console.log(obj.b); // undefined — property not set, not an error
```

